    }

    static int[] arr(String s) {
        if (s.equals("-")) {
            return new int[0];
        }
        String[] t = s.split(",");
        int[] a = new int[t.length];
        for (int i = 0; i < t.length; i++) {
            a[i] = Integer.parseInt(t[i].trim());
        }
        return a;
    }

    static String str(int[] a) {
        return Arrays.toString(a);
    }

    static String ketQua(String label, int n, String sai) {
        return sai == null ? label + ": all " + n + " agree with the brute force" : label + ": MISMATCH " + sai;
    }

    static String lst(List<List<Integer>> x) {
        List<String> s = new ArrayList<String>();
        for (List<Integer> l : x) {
            List<Integer> t = new ArrayList<Integer>(l);
            Collections.sort(t);
            s.add(t.toString());
        }
        Collections.sort(s);
        return x.size() + " " + s;
    }

    static List<List<Integer>> brute(int[] a) {
        int[] s = a.clone();
        Arrays.sort(s);
        Set<List<Integer>> set = new HashSet<List<Integer>>();
        for (int m = 0; m < (1 << s.length); m++) {
            List<Integer> l = new ArrayList<Integer>();
            for (int i = 0; i < s.length; i++) {
                if ((m >> i & 1) == 1) {
                    l.add(s[i]);
                }
            }
            set.add(l);
        }
        return new ArrayList<List<Integer>>(set);
    }

